function t(key){return copy[lang][key]||copy.en[key]||key}function applyLanguage(next){lang=copy[next]?next:'en';document.documentElement.lang=lang==='zh'?'zh-CN':lang;try{localStorage.setItem('preferredLegacyLanguage',lang);localStorage.setItem('preferredLanguage',lang)}catch{}$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$$('[data-i18n-html]').forEach(el=>el.innerHTML=t(el.dataset.i18nHtml));$$('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)));$$('[data-lang]').forEach(el=>{el.setAttribute('aria-pressed',String(el.dataset.lang===lang));el.classList.toggle('active',el.dataset.lang===lang)});$('#chat-input').placeholder=t('chat.placeholder');$('#chat-input').setAttribute('aria-label',t('chat.placeholder'));$('#archive-search').placeholder=t('search');$('#archive-search').setAttribute('aria-label',t('search'));$$('.entry-links span').forEach((el,i)=>el.textContent=(LANG_TAGS[lang]||LANG_TAGS.en)[i]);$('.detail-footer span:last-child').textContent='✓ '+t('archive.confirmed');resetChat();applyArchiveView();chooseEntry(currentKey)}
