const searchHost=$('.search-mark'),archiveSearch=document.createElement('input'),detailPanel=$('.detail-panel'),emptyState=document.createElement('p');archiveSearch.id='archive-search';archiveSearch.type='search';archiveSearch.autocomplete='off';archiveSearch.setAttribute('aria-label','Search the fictional archive');archiveSearch.style.cssText='width:100%;min-width:0;border:0;outline:0;background:transparent;color:#dce9fc;font:inherit;font-size:12px';searchHost.replaceChildren(archiveSearch);searchHost.setAttribute('role','search');archiveSearch.addEventListener('input',()=>applyArchiveView());emptyState.hidden=true;emptyState.style.cssText='margin:auto;color:#aebfda;font-size:13px;line-height:1.65;text-align:center';detailPanel.append(emptyState);$('.round-play.static').style.cursor='default';
const details={all:['1974','detail.title','detail.body','edward-sailing.png'],family:['1982','entry.4.title','entry.4.meta','mountain-walk.png'],work:['1996','entry.5.title','entry.5.meta','journal.png'],travel:['1974','detail.title','detail.body','edward-sailing.png'],letters:['1963','record.2.title','entry.2.meta','letter-1963.png'],photos:['1948','record.1.title','entry.1.meta','edward-school-portrait.png'],audio:['2010','entry.6.title','entry.6.meta','edward-portrait.png']};
