const categoryMap=['photos family','letters work','travel audio','family photos','work letters','audio family'];const entryKeys=['photos','letters','travel','family','work','audio'];$$('.archive-entry').forEach((entry,i)=>{entry.dataset.categories=categoryMap[i];entry.dataset.entryKey=entryKeys[i];entry.addEventListener('click',()=>chooseEntry(entry.dataset.entryKey))});
function applyArchiveView(){const query=$('#archive-search').value.trim().toLocaleLowerCase();const visible=$$('.archive-entry').filter(entry=>{const categoryOk=activeFilter==='all'||entry.dataset.categories.includes(activeFilter);const queryOk=!query||entry.textContent.toLocaleLowerCase().includes(query);entry.hidden=!(categoryOk&&queryOk);return !entry.hidden});const noMatches=visible.length===0;emptyState.textContent=t('search.empty');[...detailPanel.children].forEach(el=>{if(el!==emptyState)el.hidden=noMatches});emptyState.hidden=!noMatches;if(!noMatches&&!visible.some(entry=>entry.dataset.entryKey===currentKey))chooseEntry(visible[0].dataset.entryKey)}
