function message(text,who){const el=document.createElement('div');el.className=`message ${who}`;el.textContent=text;$('#messages').append(el);$('#messages').scrollTop=$('#messages').scrollHeight}function resetChat(){if(replyTimer)clearTimeout(replyTimer);const box=$('#messages');box.replaceChildren();message(t('chat.welcome'),'assistant')}
const answerFor=q=>{const lower=q.toLowerCase();if(/value|看重|価値|가치|valeur|wichtig|valor|ценност|قيمة/.test(lower))return t('chat.answer1');if(/sail|航海|항해|voile|segel|velero|veleiro|парус|شراع|بحر/.test(lower))return t('chat.answer2');if(/source|档案|材料|資料|자료|quelle|fuente|fonte|источник|مصدر/.test(lower))return t('chat.answer3');return t('chat.fallback')};
function ask(q){q=q.trim();if(!q)return;if(replyTimer)clearTimeout(replyTimer);message(q,'user');$('#chat-input').value='';const answer=answerFor(q);replyTimer=setTimeout(()=>{message(answer,'assistant');replyTimer=null},260)}
